    for r, c in markers:
        draw_star(r, c)

    # Sort markers and connect consecutive ones
    markers.sort(key=lambda x: (x[0], x[1]))
    for i in range(len(markers) - 1):
        draw_bresenham(markers[i][0], markers[i][1], markers[i+1][0], markers[i+1][1])

    return output
